import numpy as np

def mse(y_true, y_pred):
    return np.mean((y_true - y_pred) ** 2)

def mae(y_true, y_pred):
    return np.mean(np.abs(y_true - y_pred))

def huber_loss(y_true, y_pred, delta=1.0):
    error = y_true - y_pred
    is_small_error = np.abs(error) <= delta
    squared_loss = 0.5 * error ** 2
    linear_loss = delta * (np.abs(error) - 0.5 * delta)
    return np.mean(np.where(is_small_error, squared_loss, linear_loss))

y_true = np.array([10, 12, 11, 13, 50])  # 50 is a deliberate, genuine outlier
y_pred = np.array([10.5, 11.5, 11.2, 12.8, 15])  # a reasonable prediction that misses the outlier considerably

print(f"MSE: {mse(y_true, y_pred):.2f}")
print(f"MAE: {mae(y_true, y_pred):.2f}")
print(f"Huber Loss (delta=1.0): {huber_loss(y_true, y_pred, delta=1.0):.2f}")
print(f"Huber Loss (delta=5.0): {huber_loss(y_true, y_pred, delta=5.0):.2f}")

print("\nNotice MSE is dominated by the outlier's huge squared error,")
print("while Huber Loss stays considerably more moderate, treating that large error linearly instead")
